<?php require_once 'layout.php'; require_user(); $db=db(); $uid=current_user()['id']; if ($_SERVER['REQUEST_METHOD']==='POST') { $id=(int)($_POST['cart_id']??0); $act=$_POST['act']; if($act==='inc') $db->query("UPDATE cart_items SET quantity=quantity+1 WHERE id=$id AND user_id=$uid"); if($act==='dec') $db->query("UPDATE cart_items SET quantity=GREATEST(quantity-1,1) WHERE id=$id AND user_id=$uid"); if($act==='del') $db->query("DELETE FROM cart_items WHERE id=$id AND user_id=$uid"); if($act==='order') { $rows=$db->query("SELECT c.*,m.name,m.price FROM cart_items c JOIN menu_items m ON m.id=c.menu_item_id WHERE c.user_id=$uid"); $items=$rows->fetch_all(MYSQLI_ASSOC); if($items){ $total=0; foreach($items as $it)$total+=$it['price']*$it['quantity']; $token=(int)$db->query('SELECT COALESCE(MAX(token_number),1024)+1 t FROM orders')->fetch_assoc()['t']; $s=$db->prepare('INSERT INTO orders(user_id,token_number,total_amount) VALUES(?,?,?)'); $s->bind_param('iid',$uid,$token,$total); $s->execute(); $oid=$db->insert_id; $oi=$db->prepare('INSERT INTO order_items(order_id,menu_item_id,item_name,price,quantity) VALUES(?,?,?,?,?)'); foreach($items as $it){$oi->bind_param('iisdi',$oid,$it['menu_item_id'],$it['name'],$it['price'],$it['quantity']);$oi->execute();} $db->query("DELETE FROM cart_items WHERE user_id=$uid"); redirect('order_success.php?id='.$oid); } } redirect('cart.php'); } $items=$db->query("SELECT c.id cart_id,c.quantity,m.name,m.price,m.image FROM cart_items c JOIN menu_items m ON m.id=c.menu_item_id WHERE c.user_id=$uid"); page_header('My Cart'); ?><h1>My Cart</h1><div class="cart-box"><table><tr><th>Item</th><th>Price</th><th>Quantity</th><th>Total</th><th></th></tr><?php $total=0; while($i=$items->fetch_assoc()): $line=$i['price']*$i['quantity']; $total+=$line; ?><tr><td><img class="mini" src="<?=h($i['image'])?>"> <?=h($i['name'])?></td><td>₹<?=number_format($i['price'],0)?></td><td><form class="qty" method="post"><input type="hidden" name="cart_id" value="<?=$i['cart_id']?>"><button name="act" value="dec">−</button><b><?=$i['quantity']?></b><button name="act" value="inc">+</button></form></td><td>₹<?=number_format($line,0)?></td><td><form method="post"><input type="hidden" name="cart_id" value="<?=$i['cart_id']?>"><button class="ghost" name="act" value="del">🗑</button></form></td></tr><?php endwhile;?></table><div class="cart-total"><b>Total Amount</b><strong>₹<?=number_format($total,0)?></strong></div><form method="post" class="place"><button name="act" value="order" <?= $total<=0?'disabled':'' ?>>Place Order</button></form></div><?php page_footer(); ?>
